{
 "command": "ls scripts && python scripts/reconcile_ledger.py --help 2>&1 | head -30",
 "description": "List scripts and show reconcile help"
}

{
 "command": "ls var/ledger && head -5 var/ledger/2026-09.csv && wc -l var/ledger/2026-09.csv; python scripts/reconcile_ledger.py --month 2026-09; echo \"exit=$?\"",
 "description": "Inspect ledger export and run reconcile"
}

{
 "command": "python scripts/reconcile_ledger.py --month 2026-09 --format v1; echo \"exit=$?\"; cat var/ledger/2026-09.csv",
 "description": "Run reconcile with v1 format and show full export"
}
